static int xlBraceIsDictList( xvalue xItems )
{
	int iLen = xlAstArrayLen(xItems);
	if ( iLen == 0 ) return 1;
	for ( int i = 0; i < iLen; i++ ) {
		xvalue xItem = xlAstArrayGet(xItems, i);
		if ( xlAstGetKind(xItem) != AST_DICT_ENTRY ) return 0;
	}
	return 1;
}
